import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { CONFIG, type VehicleTypeId } from '../../config';

/* =====================================================================
   HÌNH HỌC XE CỘ — 3 loại (spec G1–G4): siêu xe, buýt nhỏ vàng, xe tay ga có người lái.
   Dựng theo mét, không chuẩn hóa: mũi xe về +X, rộng theo Z, mặt đường y = 0, tâm x = 0, z = 0.
   Số đo các bộ phận lấy từ bản dựng thử docs/superpowers/specs/tham-chieu/xe-co/xe-dung-thu.html (bỏ chi tiết không thấy ở 10 m).
   Mỗi đỉnh: position, normal (phẳng theo mặt), color (màu cố định ban ngày), aRole (xem Role). Có index, không uv, không texture.
   Mặt quấn ngược chiều kim đồng hồ nhìn từ ngoài (vật liệu FrontSide).
   ===================================================================== */
export enum Role { Fixed = 0, Paint = 1, Accent = 2, Head = 3, Tail = 4, Helmet = 5 }   // Paint: aPaint của instance; Accent: aAccent (áo); Helmet: aAccent.brg; Head/Tail: đèn; Fixed: color của đỉnh
export const VEHICLE_TYPES: VehicleTypeId[] = ['car', 'bus', 'bike'];

const C = CONFIG.vehicles.palette;   // màu cố định (config.ts)
export type Sec = { x: number; w: number; y0: number; ym: number; y1: number; t?: number };   // mặt cắt loft: x, nửa rộng w, đáy y0, vai ym, nóc y1, nóc hẹp còn w·t

/* Tập mặt đa giác lồi, mỗi mặt có đỉnh riêng ⇒ pháp tuyến phẳng; mặt tự lật để hướng ra xa điểm "inside" */
class Faces {
  p: number[] = []; n: number[] = []; idx: number[] = [];
  face(pts: THREE.Vector3[], inside: THREE.Vector3) {
    const nm = new THREE.Vector3(), ctr = new THREE.Vector3();
    for (let i = 0; i < pts.length; i++) {   // pháp tuyến Newell (đúng cả với tứ giác hơi vênh)
      const a = pts[i], b = pts[(i + 1) % pts.length];
      nm.x += (a.y - b.y) * (a.z + b.z); nm.y += (a.z - b.z) * (a.x + b.x); nm.z += (a.x - b.x) * (a.y + b.y); ctr.add(a);
    }
    ctr.divideScalar(pts.length);
    if (nm.dot(ctr.sub(inside)) < 0) { pts = [...pts].reverse(); nm.negate(); }
    nm.normalize();
    const base = this.p.length / 3;
    for (const v of pts) { this.p.push(v.x, v.y, v.z); this.n.push(nm.x, nm.y, nm.z); }
    for (let k = 1; k < pts.length - 1; k++) this.idx.push(base, base + k, base + k + 1);
  }
  geo(): THREE.BufferGeometry {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.p, 3)); g.setAttribute('normal', new THREE.Float32BufferAttribute(this.n, 3)); g.setIndex(this.idx);
    return g;
  }
}
const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);

/* Vỏ lượn theo các mặt cắt dọc xe: mỗi mặt cắt là lục giác (đáy, vai, nóc hẹp), nối bằng tứ giác 4 đỉnh, bịt hai đầu */
export function vhLoft(st: Sec[]): THREE.BufferGeometry {
  const f = new Faces();
  const ring = (s: Sec) => { const t = s.t ?? 0.8; return [[-s.w, s.y0], [-s.w, s.ym], [-s.w * t, s.y1], [s.w * t, s.y1], [s.w, s.ym], [s.w, s.y0]].map(([z, y]) => V(s.x, y, z)); };
  const mid = (s: Sec) => V(s.x, (s.y0 + s.y1) / 2, 0), R = st.map(ring);
  for (let i = 0; i < R.length - 1; i++) {
    const inside = mid(st[i]).add(mid(st[i + 1])).multiplyScalar(0.5);
    for (let j = 0; j < 6; j++) { const k = (j + 1) % 6; f.face([R[i][j], R[i + 1][j], R[i + 1][k], R[i][k]], inside); }
  }
  f.face(R[0], mid(st[1])); f.face(R[R.length - 1], mid(st[st.length - 2]));
  return f.geo();
}

/* Một bộ phận: bỏ uv + nhóm, gán màu đỉnh (null ⇒ trắng, màu thật lấy theo instance) và aRole */
function part(g: THREE.BufferGeometry, color: number | null, role: Role): THREE.BufferGeometry {
  if (g.getAttribute('uv')) g.deleteAttribute('uv'); g.clearGroups();
  const n = g.getAttribute('position').count, col = color === null ? new THREE.Color(1, 1, 1) : new THREE.Color(color), c = new Float32Array(n * 3), r = new Float32Array(n).fill(role);
  for (let i = 0; i < n; i++) { c[i * 3] = col.r; c[i * 3 + 1] = col.g; c[i * 3 + 2] = col.b; }
  g.setAttribute('color', new THREE.BufferAttribute(c, 3)); g.setAttribute('aRole', new THREE.BufferAttribute(r, 1));
    [[-3.3, r[1]], [-1.175, m[1]], [-1.175, m[0]], [-3.3, r[0]]], [[-1.175, m[1]], [2.3, f[1]], [2.3, f[0]], [-1.175, m[0]]]
  ];
  // các tấm áp hông cách nhau 1,5 cm: đủ xa để không z-fighting tới ~350 m (camera near 0,5 m, độ sâu 24 bit), từ phía trước không thấy độ dày
  for (const s of [1, -1]) {
    for (const q of band([2.23, 1.53], [1.49, 0.99], [1.32, 0.74])) k.side(s, 1.06, q, C.busStripeEdge);         // viền trắng (rộng hơn)
    for (const q of band([2.12, 1.64], [1.39, 1.09], [1.22, 0.84])) k.side(s, 1.075, q, C.busStripe);            // dải xanh
    k.side(s, 1.09, [[-2.9, 1.43], [2.275, 1.43], [2.275, 2.39], [-2.9, 2.39]], C.busWindow);                   // dải cửa sổ tối = khung
    for (let i = 0; i < 4; i++) { const x0 = -2.84 + i * 1.29; k.side(s, 1.105, [[x0, 1.5], [x0 + 1.19, 1.5], [x0 + 1.19, 2.32], [x0, 2.32]], C.busPane); }   // 4 ô kính trong khung (đọc ra là cửa sổ, không còn một mảng đen)
    k.side(s, 1.09, [[2.32, 1.5], [2.7, 1.5], [2.7, 1.9], [2.32, 2.4]], C.glass);                               // kính cửa lái, mép trên theo dốc kính lái
    k.box(0.06, 0.26, 0.46, 3.5, 0.74, s * 0.56, C.headDay, Role.Head);                                         // đèn pha (rộng, cao hơn để ban đêm thấy ở trung cảnh)
    k.box(0.05, 0.7, 0.14, -3.51, 1.5, s * 0.86, C.tailDay, Role.Tail);                                         // đèn hậu đứng
  }
  k.end(-3.51, [[-0.75, 1.6], [0.75, 1.6], [0.75, 2.4], [-0.75, 2.4]], C.glass);                                // kính sau
  k.box(1.6, 0.1, 1.3, -1.0, 2.73, 0, C.busAc);                                                                 // điều hòa nóc (đỉnh 2,78 m, chân lún 2 cm vào nóc 2,7 m)
  for (const x of [2.3, -1.9]) for (const z of [0.93, -0.93]) k.wheel(0.4, 0.3, x, z);
}

/* Xe tay ga + người lái (~1,8 m, cao tới đỉnh mũ ~1,6 m): bánh, thân sau, sàn, yếm, chắn bùn, phuộc, ghi đông, đèn, yên; người lái áo / mũ theo instance */
function vhBike(k: Kit) {
  for (const x of [0.6, -0.58]) k.wheel(0.24, 0.11, x, 0);
  k.loft([
    { x: -0.9, w: 0.11, y0: 0.46, ym: 0.6, y1: 0.68, t: 0.7 }, { x: -0.56, w: 0.2, y0: 0.3, ym: 0.6, y1: 0.74, t: 0.7 },
    { x: -0.1, w: 0.19, y0: 0.27, ym: 0.55, y1: 0.72, t: 0.7 }, { x: 0.06, w: 0.16, y0: 0.25, ym: 0.3, y1: 0.34, t: 0.9 }
  ], null, Role.Paint);                                                                                          // thân sau
  k.box(0.4, 0.06, 0.34, 0.22, 0.29, 0, null, Role.Paint);                                                      // sàn để chân
  k.box(0.07, 0.72, 0.4, 0.44, 0.64, 0, null, Role.Paint, 0.2);                                                 // yếm nghiêng
  k.box(0.42, 0.07, 0.15, 0.6, 0.52, 0, null, Role.Paint, -0.1);                                                // chắn bùn trước
  k.box(0.06, 0.5, 0.06, 0.54, 0.5, 0, C.dark, Role.Fixed, 0.2);                                                // phuộc
  k.box(0.12, 0.1, 0.3, 0.4, 1.02, 0, null, Role.Paint); k.box(0.05, 0.05, 0.7, 0.36, 1.03, 0, C.dark);        // đầu xe + ghi đông
  k.box(0.06, 0.18, 0.26, 0.48, 0.98, 0, C.headDay, Role.Head);                                               // đèn pha (một đèn, to hơn để ban đêm thấy ở trung cảnh)
  k.box(0.72, 0.09, 0.3, -0.42, 0.78, 0, C.seat);                                                               // yên
  k.box(0.05, 0.08, 0.14, -0.92, 0.6, 0, C.tailDay, Role.Tail);                                                 // đèn hậu
  // người lái
  k.box(0.24, 0.56, 0.36, -0.27, 1.12, 0, null, Role.Accent, -0.12);                                            // thân áo
  k.box(0.17, 0.17, 0.16, -0.18, 1.46, 0, C.skin);                                                              // mặt
  k.dome(0.13, -0.21, 1.5, 0, null, Role.Helmet);                                                               // mũ bảo hiểm
  for (const z of [0.2, -0.2]) k.box(0.68, 0.08, 0.08, 0.1, 1.2, z, null, Role.Accent, -0.49);                  // tay tới ghi đông
  for (const z of [0.13, -0.13]) { k.box(0.46, 0.13, 0.13, -0.1, 0.86, z, C.trouser, Role.Fixed, -0.1); k.box(0.11, 0.48, 0.11, 0.15, 0.58, z, C.trouser, Role.Fixed, -0.2); }   // đùi + ống chân
}
const BUILDERS: Record<VehicleTypeId, (k: Kit) => void> = { car: vhCar, bus: vhBus, bike: vhBike };

const cache = new Map<VehicleTypeId, THREE.BufferGeometry>();
export function vhBuildTypeGeometry(type: VehicleTypeId): THREE.BufferGeometry {
  if (!cache.has(type)) { const k = new Kit(); BUILDERS[type](k); cache.set(type, k.build()); }
  return cache.get(type)!;
}

/* Gộp 3 loại thành một hình học; aPart = chỉ số loại trong VEHICLE_TYPES (vertex shader thu đỉnh khác loại về gốc) */
let fleet: THREE.BufferGeometry | null = null;
export function vhBuildFleetGeometry(): THREE.BufferGeometry {
  if (fleet) return fleet;
  const parts = VEHICLE_TYPES.map((t, i) => {
    const g = vhBuildTypeGeometry(t).clone(), n = g.getAttribute('position').count;
    g.setAttribute('aPart', new THREE.BufferAttribute(new Float32Array(n).fill(i), 1));
    return g;
  });
  fleet = mergeGeometries(parts, false)!; fleet.computeBoundingBox(); fleet.computeBoundingSphere();
  return fleet;
}
    for (const im of this.meshes) { this.group.remove(im); im.dispose(); }
    this.meshes = []; this.src = null; this.used.fill(false); this.group.visible = false;
  }
}
const B3 = new THREE.Quaternion();
export const drWheels = new DrWheelPool();

/* ===== Hình tạm và tấm bóng dùng chung ===== */
let tempMat: THREE.MeshStandardMaterial | null = null, shadowMat: THREE.MeshBasicMaterial | null = null, shadowGeo: THREE.PlaneGeometry | null = null, shadowTex: THREE.DataTexture | null = null;

function drTempGeometry(color: string): THREE.BufferGeometry {
  const L = CAR.length, W = CAR.width, H = CAR.height - CAR.clearance, r = CAR.wheelDia / 2, ww = M.temp.wheelWidth;
  const col = new THREE.Color(color), dark = new THREE.Color(0x15151a);
  const paint = (g: THREE.BufferGeometry, c: THREE.Color): THREE.BufferGeometry => {
    const n = g.attributes.position.count, a = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) { a[i * 3] = c.r; a[i * 3 + 1] = c.g; a[i * 3 + 2] = c.b; }
    g.setAttribute('color', new THREE.BufferAttribute(a, 3));
    return g;
  };
  const parts: THREE.BufferGeometry[] = [paint(new RoundedBoxGeometry(L, H, W, 2, 0.12).translate(0, CAR.clearance + H / 2, 0), col)];
  const ax = CAR.wheelbase / 2, az = W / 2 - ww / 2;
  for (const sx of [1, -1]) for (const sz of [1, -1]) {
    parts.push(paint(new THREE.CylinderGeometry(r, r, ww, 12).rotateX(Math.PI / 2).translate(sx * ax, r, sz * az), dark));
  }
  const g = mergeGeometries(parts.map((p) => p.index ? p.toNonIndexed() : p))!;   // 1 Mesh gộp
  for (const p of parts) p.dispose();
  return g;
}

function drShadowShared(): void {
  if (shadowMat) return;
  const n = 32, d = new Uint8Array(n * n * 4);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;   // mép mềm hình vuông bo
    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
  }
  shadowTex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); shadowTex.needsUpdate = true;
  shadowTex.magFilter = shadowTex.minFilter = THREE.LinearFilter;
  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: shadowTex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
  shadowMat.name = 'driveShadow';
  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
}
function drTempMaterial(): THREE.MeshStandardMaterial {
  if (!tempMat) { tempMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6, metalness: 0.1 }); tempMat.name = 'driveTemp'; }
  return tempMat;
}
/* Giải phóng vật liệu / bánh dùng chung (rời chế độ hẳn) */
export function drCarDisposeShared(): void {
  drWheels.reset();
  tempMat?.dispose(); tempMat = null;
  shadowMat?.dispose(); shadowGeo?.dispose(); shadowTex?.dispose(); shadowMat = null; shadowGeo = null; shadowTex = null;
}

/* ===== Một xe ===== */
export class DrCar {
  readonly group = new THREE.Group();
  private readonly color: string;
  private temp: THREE.Mesh | null;
  private tempGeo: THREE.BufferGeometry | null;
  private shadow: THREE.Mesh;
  private body: THREE.Object3D | null = null;
  private paint: THREE.MeshStandardMaterial | null = null;
  private tailMeshes: THREE.Mesh[] = [];
  private src: DrSource | null = null;
  private slot = -1;
  private disposed = false;
  private brakingNow = false;
  private last: DrPlace | null = null;

  constructor(color: string) {
    this.color = color;
    this.group.name = 'drive-car';
    this.group.matrixAutoUpdate = true;
    this.tempGeo = drTempGeometry(color);
    this.temp = new THREE.Mesh(this.tempGeo, drTempMaterial());
    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
    this.group.add(this.temp);
    drShadowShared();
    this.shadow = new THREE.Mesh(shadowGeo!, shadowMat!);
    this.shadow.scale.set(CAR.length + 2 * M.shadow.pad, 1, CAR.width + 2 * M.shadow.pad);
    this.shadow.position.y = M.shadow.lift;
    this.shadow.layers.set(1); this.shadow.castShadow = false; this.shadow.receiveShadow = false; this.shadow.renderOrder = 1;
    this.group.add(this.shadow);
    void drCarLoad();
    late!.then((scene) => { const src = scene && sources.get(scene); if (src && !this.disposed) this.swap(src); });   // không bao giờ từ chối; nguồn của bộ nạp cũ (test đổi bộ nạp) thì bỏ
  }

  get real(): boolean { return this.body !== null; }

  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
  private swap(src: DrSource): void {
    if (this.body) return;
    drWheels.setup(src);
    this.slot = drWheels.acquire();
    this.src = src;
    const body = src.body.clone();
    this.paint = src.paint.clone();
    this.paint.color.set(this.color); this.paint.roughness = M.paintRough; this.paint.metalness = M.paintMetal;
    body.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      const mat = m.material as THREE.Material;
      if (mat.name === 'paint') m.material = this.paint!;
      else if (mat === src.tail) this.tailMeshes.push(m);
    });
    this.body = body;
    this.group.add(body);
    if (this.temp) { this.group.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
    this.brakingNow = false;
    if (this.last) this.place(this.last);
  }

  place(p: DrPlace): void {
    const l = this.last || (this.last = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, steer: 0, wheel: 0, braking: false });
    l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.steer = p.steer; l.wheel = p.wheel; l.braking = p.braking;
    const g = this.group;
    g.position.set(p.x, p.y, p.z);
    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(B3.setFromAxisAngle(AXZ, p.pitch));
    if (!this.body) return;
    if (p.braking !== this.brakingNow) {
      this.brakingNow = p.braking;
      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
      for (const m of this.tailMeshes) m.material = mat;
    }
    if (this.slot >= 0) { g.updateMatrix(); drWheels.set(this.slot, g.matrix, p.steer, p.wheel); }
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.group.removeFromParent();
    drWheels.release(this.slot); this.slot = -1;
    this.tempGeo?.dispose(); this.tempGeo = null;
    this.paint?.dispose(); this.paint = null;
    this.body = null; this.temp = null; this.tailMeshes.length = 0;
  }
