  out.lean = await page.evaluate(() => { const B = window.__app.bike; for (let i = 0; i < 10; i++) B.step(0.1, { gas: 1, brake: 0, steer: 1, hard: false, grip: 1 }); return { lean: B.state.lean, v: B.state.v }; });
  await frames(page, 2);
  await page.screenshot({ path: 'tests/screens/bike-lean.png' });
  /* dốc dẫn Cầu Rồng phía Tây: x = −300, đi Đông (lên dốc) — nhìn ngang từ phía Nam (+Z) */
  out.ramp = await page.evaluate(() => {
