    const s = B.state; A.cam.mode = 'swRide';   // tạm khóa camera (bike không chạy khung), đặt tay
    A.camera.position.set(s.x, s.y + 0.8, s.z + 4.5); A.camera.lookAt(s.x, s.y + 0.6, s.z);
    const g = A.scene.getObjectByName('bike'); const v = new A.THREE.Vector3(1, 0, 0).applyQuaternion(g.quaternion);
    return { pitch: s.pitch, y: s.y, noseDirY: v.y };
  });
  await frames(page, 3);
  await page.screenshot({ path: 'tests/screens/bike-ramp.png' });
  await page.evaluate(() => { window.__app.cam.mode = 'bike'; });
  /* thoát / vào lại: bike.stop(); drive.start() ⇒ thân ô tô (khe 1,2 m không lọt) */
  out.swap = await page.evaluate(() => {
    const A = window.__app; A.bike.stop(); const afterStop = { mode: A.cam.mode, cls: document.body.className, inScene: !!A.scene.getObjectByName('bike')?.parent };
    A.drive.start(); const D = A.drive, n = D.net, sameNet = n === A.bike.net;
    /* khe 1,2 m dựng bằng hai vật cản thêm tạm vào net dùng chung, trên ô mặt đường nơi xe đứng */
    const s = D.state, x0 = s.x + 6, y = s.y;
